def to_binary(n):
    return bin(n)[2:]

def from_binary(bits):
    return int(bits, 2)

def to_binary(n):
    if n < 2:
        return str(n)
    return to_binary(n // 2) + str(n % 2)

def from_binary(bits):
    total = 0
    for place, bit in enumerate(reversed(bits)):
        total += int(bit) * 2 ** place
    return total
